SELECT REGEXP_SUBSTR('ABC-123-XYZ', '[0-9]+') AS A,
       REGEXP_COUNT('banana', 'a')              AS B
  FROM DUAL;

SELECT CNO
  FROM CONTACT
 WHERE REGEXP_LIKE(PHONE, '^010-[0-9]{4}-[0-9]{4}$');

SELECT REGEXP_REPLACE('2026-11-04', '[^0-9]', '') AS A,
       REGEXP_INSTR('a1b22c333', '[0-9]{2}')     AS B
  FROM DUAL;
